    {
      "hex": "#f3ecf7",
      "name": "Lilac Mist",
      "level": 1,
      "purpose": "First elevated surface — table rows, subtle section differentiation, light card backgrounds"
    },
    {
      "hex": "#e9f3e7",
      "name": "Pastel Tints",
      "level": 2,
      "purpose": "Card surface family — each card picks from mint, peach, pink, blue, or sky tints"
    },
    {
      "hex": "#ffffff",
      "name": "Pure White",
      "level": 3,
      "purpose": "Product screenshot frames, modal surfaces, cookie bar — the most elevated layer"
    }
  ],
  "elevationPhilosophy": "This system deliberately avoids drop-shadow elevation. Depth is created through three mechanisms: (1) warm Parchment canvas beneath white cards, (2) vivid 2px colored borders that frame each card as a labeled specimen, and (3) subtle surface tint shifts between Lilac Mist, pastel tints, and pure white. The result is a flat, editorial, almost botanical-illustration quality — cards feel pinned to the page rather than floating above it.",
  "imagery": "Imagery is illustrative and decorative rather than photographic. Hand-drawn line illustrations of clouds, paper planes, sprouts, vines, satellites, and botanical elements float across sections in Deep Iris #4d3e78 line work with occasional accent-color fills (Orchid Pink, Tangerine, Forest Fern). The illustrations overlap hero copy and product mockups, creating a layered, scrapbook-like atmosphere. Product screenshots appear as white-carded UI frames showing workflow node graphs, forms, and dashboards — the product is the hero, not stock photography. No live-action photos anywhere; the visual language is 100% illustration + product UI.",
  "layout": "Max-width 1200px centered with full-bleed warm Parchment canvas. Hero opens with centered Reckless headline over violet-illustration atmosphere, flanked by floating product-screenshot cards at slight overlapping angles. Below the fold: logo strip on white band, then alternating sections — text-left/mockup-right and text-right/mockup-left in a 2-column 50/50 split at 80px vertical gaps. Testimonial section uses a dense 3-4 column grid of pastel specimen cards with 24px gaps. Navigation is a centered floating pill bar at the top with 4 primary items, login/signup links, and a filled Book a demo button on the right. Sections flow seamlessly without dividers — depth comes from surface tints, not lines.",
  "customSections": [
    {
      "title": "Agent Prompt Guide",
      "content": "$1e"
    },
